    public List<int> MergeKSortedArrays(int[][] arr, int k) {

        // Raj Thomas 1st Aug 2026 11:58PM IST

        // PriorityQueue<(int value, int row, int idx), int> pq = new PriorityQueue<(int value, int row, int idx), int>();
        SortedSet<(int, int, int)> pq = new SortedSet<(int, int, int)>(
            Comparer<(int, int, int)>.Create((a, b) =>
            {
                if (a.Item1 != b.Item1) return a.Item1.CompareTo(b.Item1);
                if (a.Item2 != b.Item2) return a.Item2.CompareTo(b.Item2);
                return a.Item3.CompareTo(b.Item3);
            })
        );

        for(int i = 0; i < arr.Length; i++) {
            pq.Add((arr[i][0], i, 0));
        }

        List<int> result = new List<int>();

        while(pq.Count > 0) {
            var node = pq.Min;
            int val = node.Item1;
            int row = node.Item2;
            int col = node.Item3;

            result.Add(val);
            pq.Remove(node);
            if (col + 1 < arr[row].Length) {
                pq.Add((arr[row][col + 1], row, col + 1));
            }
        }

        return result;
    }
}

