from typing import List


class Solution:
    # Merges all arrays by sorting every value.
    def mergeKArrays(self, arrays: List[List[int]]) -> List[int]:
        result: List[int] = []

        # Copy every value into one result array.
        for current_array in arrays:
            for value in current_array:
                result.append(value)

        # Sort all copied values into global order.
        result.sort()

        return result


# Driver code
def main() -> None:
    arrays = [[1, 4, 5], [1, 3, 4], [2, 6]]
    obj = Solution()
    print(obj.mergeKArrays(arrays))


if __name__ == "__main__":
    main()
